function spawnRecurring(){const t=new Date().toDateString();if(lastSpawnDay===t)return;lastSpawnDay=t;let n=0;state.quests.slice().forEach(q=>{if(q.repeat!=="daily"||q.status==="active")return;const ref=new Date(q.completedAt||q.failedAt||q.createdAt);if(ref.toDateString()===t)return;let deadline=null;if(q.deadline){const od=new Date(q.deadline),nd=new Date();nd.setHours(od.getHours(),od.getMinutes(),0,0);if(nd.getTime()<=Date.now())nd.setDate(nd.getDate()+1);deadline=nd.toISOString();}q.repeat="none";state.quests.unshift({...q,id:uid(),status:"active",repeat:"daily",createdAt:dateNow(),completedAt:null,failedAt:null,failureReason:null,penaltyCreated:false,dcShielded:false,boostXP:false,boostDC:false,ringDouble:false,redPenaltyDone:false,focusSeconds:0,focusSessions:0,deadline});n++;});if(n){logActivity(`تجديد ${n} مهمة يومية`);save();}}
function activeItem(id){return state.inventory.find(i=>i.id===id&&i.qty>0);}
function completeQuest(id){const q=state.quests.find(q=>q.id===id);if(!q||q.status!=="active")return;if(q.focusMinutes>0&&(q.focusSeconds||0)<q.focusMinutes*60){toast(`المهمة مرتبطة بجلسة ${q.focusMinutes} دقيقة. أكمل جلسة التركيز أولًا.`);return;}if(pendingPenalties().length){toast("عندك عقوبة مستحقة. نفّذها أولًا لتحصيل مكافأة المهمة.");go("penalties");return;}const xp=q.xpReward,dc=q.dcReward;if(!Number.isFinite(xp)||!Number.isFinite(dc))return;let earnedXP=xp,earnedDC=dc;const activeTitle=state.profile.activeTitle||"";if(/مبرمج|programmer/i.test(activeTitle)&&q.stat==="intelligence")earnedXP=Math.ceil(earnedXP*1.1);if(q.boostXP){earnedXP=Math.min(100,Math.ceil(earnedXP*1.1));q.boostXP=false;}if(state.xpPotionBoost>0){earnedXP=Math.ceil(earnedXP*1.25);state.xpPotionBoost--;}if(q.randomGate)earnedXP=Math.ceil(earnedXP*2);if(state.awakening&&state.awakening.status==="passed")earnedXP=Math.ceil(earnedXP*1.15);if(q.boostDC){earnedDC=Math.min(25,Math.ceil(dc*1.2));q.boostDC=false;}const fx=v9ApplyCompletionBonuses(q,earnedXP,earnedDC);earnedXP=fx.xp;earnedDC=fx.dc;state.xp+=earnedXP;state.coins+=earnedDC;state.stats[q.stat]=Math.min(999,(state.stats[q.stat]||1)+Math.max(1,Math.floor(earnedXP/20)));q.status="done";q.completedAt=dateNow();if(state.awakening&&state.awakening.status==="active")progressAwakening();if(q.goalId){const g=state.mainGoals.find(x=>x.id===q.goalId);if(g){g.completedTasks=(g.completedTasks||0)+1;const m=(g.milestones||[]).find(x=>x.id===q.goalMilestoneId)||g.milestones?.find(x=>!x.done);if(m)m.done=true;g.updatedAt=dateNow();}}state.archive=state.archive||[];state.archive.unshift({type:"quest_done",text:"أكملت المهمة: "+q.name,at:dateNow()});state.archive=state.archive.slice(0,300);updateLevel();let today=new Date().toDateString();if(!state.lastCompleteDate||new Date(state.lastCompleteDate).toDateString()!==today){state.streak=state.lastCompleteDate&&new Date(state.lastCompleteDate).toDateString()===new Date(Date.now()-86400000).toDateString()?state.streak+1:1;state.lastCompleteDate=dateNow();}transaction("إكمال: "+q.name,earnedDC,"in");logActivity("أكملت المهمة: "+q.name,"success");checkShadows();queueDungeonMilestones();if(state.streak>=7&&!state.titles.includes("Consistent Hunter"))state.titles.push("Consistent Hunter");save();render();v9Alert("QUEST COMPLETED",`+${earnedXP} XP · +${earnedDC} DC`,"completed");toast(`تم إكمال المهمة! +${earnedXP} XP و +${earnedDC} DC${fx.notes}`);setTimeout(promptDungeonIfNeeded,180);}
function consumeInventory(id){const item=activeItem(id);if(item){item.qty--;if(item.qty<=0)state.inventory=state.inventory.filter(i=>i.qty>0);}}
function failQuest(id){const q=state.quests.find(q=>q.id===id);if(!q||q.status!=="active")return;openFailureReason({questId:id});}
function openFailureReason({questId="",penaltyId=""}={}){const dialog=$("failureReasonDialog");if(!dialog){toast("نافذة تسجيل سبب الفشل غير متاحة.");return;}$("failureReasonQuestId").value=questId;$("failureReasonPenaltyId").value=penaltyId;const q=state.quests.find(x=>x.id===questId);const p=state.penalties.find(x=>x.id===penaltyId);$("failureReasonSubject").textContent=q?`المهمة: ${q.name}`:p?`العقوبة: ${p.name}`:"سجّل السبب الأساسي للتعثر.";$("failureReasonInput").value="";dialog.showModal();setTimeout(()=>$("failureReasonInput").focus(),0);}
function recordQuestFailure(id,reason){const q=state.quests.find(q=>q.id===id);if(!q||q.status!=="active")return;q.status="failed";q.failedAt=dateNow();q.failureReason=reason;state.failureReasons.unshift({id:uid(),questId:q.id,questName:q.name,reason,at:dateNow()});state.failureReasons=state.failureReasons.slice(0,200);const helmetBlock=!q.dcShielded&&v9HelmetBlocks(q);const shieldProtected=!!q.dcShielded||helmetBlock;if(helmetBlock){}else if(shieldProtected){q.dcShielded=false;logActivity("درع الانضباط منع خصم العملات عن: "+q.name,"success");}else{const loss=Math.max(0,Math.min(5,state.coins)-v9LossReduction());state.coins-=loss;if(loss>0)transaction("خصم بسبب فشل: "+q.name,-loss,"out");}if(!q.penaltyCreated){state.penalties.unshift({id:uid(),name:"مراجعة سبب الفشل: "+q.name,reason:"انتهى موعد المهمة أو تم تسجيل فشلها",failureReason:reason,type:"missed",done:false,createdAt:dateNow(),questId:q.id});q.penaltyCreated=true;}else{const p=state.penalties.find(x=>x.questId===q.id&&!x.done);if(p)p.failureReason=reason;}logActivity("فشل المهمة: "+q.name,"danger");state.archive=state.archive||[];state.archive.unshift({type:"quest_failed",text:"تعثر: "+q.name+" — "+reason,at:dateNow()});state.archive=state.archive.slice(0,300);v9AfterFail(q,"manual");save();render();toast(shieldProtected?"تم تسجيل سبب الفشل وإنشاء العقوبة دون خصم العملات.":"تم تسجيل سبب الفشل وخصم حتى 5 DC وإنشاء عقوبة.");}function deleteQuest(id){const target=state.quests.find(q=>q.id===id);if(state.settings.strictMode&&target&&Date.now()-new Date(target.createdAt).getTime()>10*60*1000){toast("Strict Mode: لا يمكن حذف المهمة بعد مرور 10 دقائق.");return;}confirmAction("حذف المهمة","سيتم حذف المهمة من القائمة. لا يمكن التراجع عن الحذف إلا باستعادة نسخة احتياطية.",()=>{const q=state.quests.find(q=>q.id===id);state.quests=state.quests.filter(q=>q.id!==id);logActivity("حذف مهمة: "+(q?.name||"غير معروفة"));save();render();toast("تم حذف المهمة");});}
function checkDeadlines(){let changed=false,penaltyAdded=false;const now=Date.now();state.quests.forEach(q=>{if(q.status==="active"&&q.deadline&&new Date(q.deadline).getTime()<now&&!q.penaltyCreated){q.status="failed";if(q.randomGate){q.failedAt=dateNow();q.penaltyCreated=true;changed=true;return;}q.failedAt=dateNow();q.penaltyCreated=true;state.penalties.unshift({id:uid(),name:"مراجعة سبب الفشل: "+q.name,reason:"انتهى الموعد النهائي تلقائيًا",type:"missed",done:false,createdAt:dateNow(),questId:q.id});penaltyAdded=true;logActivity("انتهى موعد المهمة: "+q.name,"danger");v9AfterFail(q,"auto");changed=true;}});if(changed){save();if(penaltyAdded)showNotice("انتهى موعد مهمة واحدة أو أكثر. تمت إضافة العقوبات إلى قائمة العقوبات المستحقة.");}}
function addPenalty(){const name=$("penaltyName").value.trim();if(!name)return;const id=uid(),reason=$("penaltyReason").value.trim(),type=$("penaltyType").value,focusOn=!!$("penaltyFocusToggle")?.checked,hours=focusOn?Math.max(.5,Math.min(12,Number($("penaltyFocusHours").value)||1)):0,focusMinutes=Math.round(hours*60),focusLabel=focusMinutes<60?focusMinutes+" دقيقة":focusMinutes%60?Math.floor(focusMinutes/60)+" س "+focusMinutes%60+" د":focusMinutes/60+" ساعة";state.penalties.unshift({id,name,reason,type,focusMinutes,focusSession:!!focusMinutes,done:false,createdAt:dateNow()});if($("penaltyZoneTaskToggle")?.checked||focusOn){state.customPenaltyTasks=state.customPenaltyTasks||[];state.customPenaltyTasks.unshift({id:"custom-"+id,text:focusMinutes?name+" — جلسة تركيز "+focusLabel:name,kind:focusMinutes?"timer":"manual",ms:focusMinutes*60000,focusMinutes,focusSession:!!focusMinutes,noFocusLog:true,createdAt:dateNow(),sourcePenaltyId:id});}logActivity("إضافة عقوبة: "+name,"danger");$("penaltyDialog").close();save();render();toast(focusMinutes?"تمت إضافة العقوبة مع جلسة تركيز زمنية؛ لن تُضاف لتحليلات التركيز.":$("penaltyZoneTaskToggle")?.checked?"تمت إضافة العقوبة للقائمة ولاختيارات نافذة منطقة العقوبة.":"تمت إضافة العقوبة");}
function completePenalty(id){const p=state.penalties.find(p=>p.id===id);if(!p||p.done)return;if(p.type==="missed"){const linked=state.quests.find(q=>q.id===p.questId);const reason=String(p.failureReason||linked&&linked.failureReason||"").trim();if(!reason){openFailureReason({questId:linked&&linked.id||"",penaltyId:p.id});toast("اكتب سبب التعثر أولًا قبل تأكيد تنفيذ العقوبة.");return;}p.failureReason=reason;}confirmAction("تأكيد تنفيذ العقوبة","هل نفذت هذه المهمة فعلًا؟ سجّلها مكتملة فقط بعد تنفيذها.",()=>{p.done=true;p.completedAt=dateNow();logActivity("تنفيذ العقوبة: "+p.name,"success");save();render();toast("تم تسجيل تنفيذ العقوبة. يمكنك الآن تحصيل مكافآت المهام.");});}
function buyItem(id){if(!shopUnlocked()){toast("المتجر يُفتح عند رتبة A فقط.");return;}const item=SHOP.find(x=>x.id===id);if(!item)return;if(item.kind==="equipment"&&activeItem(id)){toast("هذه المعدة مملوكة بالفعل.");return;}if(state.coins<item.price){toast("رصيدك غير كافٍ لشراء هذا العنصر.");return;}if(pendingPenalties().length){toast("نفّذ العقوبات المستحقة قبل الشراء.");return;}state.coins-=item.price;const existing=state.inventory.find(i=>i.id===id);if(existing)existing.qty++;else state.inventory.push({id,qty:1,boughtAt:dateNow()});if(item.kind==="equipment")v9().equip[id]=true;transaction("شراء: "+item.ar,-item.price,"out");logActivity("شراء عنصر: "+item.ar);save();render();toast("تم شراء "+item.ar+" وإضافته للمخزون");}
function useItem(id){if(!shopUnlocked())return;const item=activeItem(id);if(!item)return;if(v9UseItem(id))return;if(id==="elixir"){state.xpPotionBoost=(state.xpPotionBoost||0)+1;consumeInventory(id);logActivity("استخدام إكسير الصحوة");toast("إكسير الصحوة نشط للمهمة التالية: XP +25%.");}else if(id==="time"){const active=state.quests.filter(q=>q.status==="active"&&q.deadline&&new Date(q.deadline).getTime()>Date.now());if(!active.length){toast("لا توجد مهمة نشطة لها موعد مستقبلي. العنصر لم يُستهلك.");return;}const choice=active[0];choice.deadline=new Date(new Date(choice.deadline).getTime()+2*60*60*1000).toISOString();consumeInventory(id);logActivity("تمديد موعد المهمة ساعتين: "+choice.name);toast("تم تمديد أقرب موعد ساعتين: "+choice.name);}else if(id==="leisure"){consumeInventory(id);logActivity("تفعيل تصريح الترفيه: ساعتان مخطط لهما");state.titles.includes("Balanced Hunter")||state.titles.push("Balanced Hunter");toast("تم تسجيل ساعتين ترفيه مخطط لهما. استمتع بدون تأنيب.");}else if(id==="shield"){const q=state.quests.find(q=>q.status==="active"&&!q.dcShielded);if(!q){toast("لا توجد مهمة نشطة لتعيين الدرع لها.");return;}q.dcShielded=true;consumeInventory(id);logActivity("تفعيل درع الانضباط للمهمة: "+q.name);toast("الدرع فعّال للمهمة: "+q.name);}else if(id==="sword"){const q=state.quests.find(q=>q.status==="active"&&!q.boostXP);if(!q){toast("لا توجد مهمة نشطة لتفعيل السيف عليها.");return;}q.boostXP=true;consumeInventory(id);logActivity("تفعيل سيف التركيز للمهمة: "+q.name);toast("تم تفعيل زيادة XP للمهمة: "+q.name);}else if(id==="spear"){const q=state.quests.find(q=>q.status==="active"&&!q.boostDC);if(!q){toast("لا توجد مهمة نشطة لتفعيل الرمح عليها.");return;}q.boostDC=true;consumeInventory(id);logActivity("تفعيل رمح الصياد للمهمة: "+q.name);toast("تم تفعيل زيادة DC للمهمة: "+q.name);}save();render();}
function checkShadows(){const total=state.quests.filter(q=>q.status==="done").length;SHADOWS.forEach(s=>{if(total>=s.at&&!state.shadows.includes(s.id)){state.shadows.push(s.id);logActivity("استخراج ظل جديد: "+s.name,"success");if(!state.titles.includes(s.name))state.titles.push(s.name);}});}
function queueDungeonMilestones(){const done=state.quests.filter(q=>q.status==="done").length,ds=state.dungeonSystem;for(let milestone=10;milestone<=done;milestone+=10){if(!ds.triggeredMilestones.includes(milestone)){ds.triggeredMilestones.push(milestone);ds.pendingMilestones.push(milestone);logActivity(`ظهرت زنزانة جديدة بعد إكمال ${milestone} مهمة` ,"success");}}}
const DUNGEON_BOSS_ART=["Gemini_Generated_Image_69juvp69juvp69ju.jpg","Gemini_Generated_Image_8dpjcw8dpjcw8dpj.jpg","Gemini_Generated_Image_n8xhjqn8xhjqn8xh.jpg","Gemini_Generated_Image_otk0seotk0seotk0.jpg","Gemini_Generated_Image_rjvrqwrjvrqwrjvr.jpg"];
