function offerRandomGate(){const day=new Date().toDateString();if(state.randomGateDate===day)return;state.randomGateDate=day;if(Math.random()>.12){save();return;}const choices=["رتّب مكتبك لعشر دقائق","راجع عشرة أسطر من كود أو ملاحظات","اقرأ خمس صفحات وسجّل فكرة واحدة"];const name=choices[Math.floor(Math.random()*choices.length)];state.quests.unshift({id:uid(),name:"بوابة طارئة: "+name,type:"emergency",stat:"discipline",difficulty:"normal",xpReward:35,dcReward:8,deadline:new Date(Date.now()+30*60000).toISOString(),description:"تحدٍ اختياري لمدة 30 دقيقة. مكافأة XP مضاعفة.",focusMinutes:0,repeat:"none",status:"active",createdAt:dateNow(),completedAt:null,penaltyCreated:false,sideQuest:true,randomGate:true});save();render();v9Alert("EMERGENCY GATE",name+" · 30 دقيقة · XP ×2","received");}function renderAwakening(){const a=state.awakening||(state.awakening={status:"locked",progress:0});const box=$("awakeningStatus"),prog=$("awakeningProgress"),btn=$("awakeningBtn");if(!box)return;if(rankIndex()>=3&&a.status==="locked")a.status="ready";box.textContent=a.status==="locked"?"مقفل حتى رتبة B":a.status==="ready"?"جاهز للاختبار":a.status==="active"?"الاختبار جارٍ "+a.progress+" / 3":"تم الاستيقاظ · +15% XP";if(prog)prog.textContent=a.status==="active"?"أكمل "+(3-a.progress)+" مهمات":a.status==="passed"?"ثيم الملك فُعّل ومكافأة الصحوة دائمة.":"تحدي من 3 مهمات بعد رتبة B.";if(btn){btn.disabled=a.status==="locked"||a.status==="active"||a.status==="passed";btn.textContent=a.status==="passed"?"تم الاجتياز ✓":a.status==="active"?"أكمل المهمات الثلاث":a.status==="ready"?"ابدأ اختبار المهنة":"مقفل حتى رتبة B";}if(a.status==="passed"){document.body.dataset.hunterTheme="monarch";}}function startAwakening(){const a=state.awakening;if(a.status!=="ready")return;a.status="active";a.progress=0;save();render();toast("بدأ اختبار Awakening: أكمل 3 مهمات لاجتياز تغيير المهنة.");}function progressAwakening(){const a=state.awakening;if(a.status!=="active")return;a.progress++;if(a.progress>=3){a.status="passed";logActivity("اجتياز Job Change Event — Shadow Monarch","success");}save();}function render(){updateLevel();renderAwakening();ensureV9();const r=rank(),done=state.quests.filter(q=>q.status==="done").length,active=state.quests.filter(q=>q.status==="active").length,pen=pendingPenalties().length,level=levelProgress();$("rankBadge").textContent="RANK "+r.name;$("coinBalance").textContent=state.coins;$("shopCoins").textContent=state.coins;$("heroCoins").textContent=state.coins;$("playerNameSide").textContent=state.profile.name||"HUNTER";renderAvatar();$("playerLevelSide").textContent="LEVEL "+state.level;$("todayLabel").textContent=new Date().toLocaleDateString("ar-EG",{weekday:"short",month:"short",day:"numeric"});$("heroRank").textContent=r.title;$("heroQuote").textContent=state.profile.goal?("MAIN QUEST: "+state.profile.goal):"ابدأ صغيرًا. التزم. تطوّر.";$("levelText").textContent="LEVEL "+state.level;$("xpText").textContent=`${level.earned.toLocaleString()} / ${level.needed.toLocaleString()} XP`;$("xpBar").style.width=level.percent+"%";$("completedTotal").textContent=done;$("penaltyCount").textContent=pen;$("shopLockLabel").textContent=shopUnlocked()?"✓":"A";renderStats();renderDashboard();renderQuests();renderDungeons();renderShadows();renderShop();renderAnalytics();renderPenalties();renderEvolution();renderSettings();renderGrowth();renderAchievements();renderMastery();if($("view-assistant")&&$("view-assistant").classList.contains("active"))renderAiAssistant();v9Render();$("profileForm")&&($("playerName").value=state.profile.name||"");syncPenaltyNotice();}
function derivedStats(){const done=state.quests.filter(q=>q.status==="done"),failed=state.quests.filter(q=>q.status==="failed"),focus=(state.focusLogs||[]).reduce((n,x)=>n+(x.minutes||0),0);const rate=(done.length+failed.length)?done.length/(done.length+failed.length):0;const out={};for(const st of STATS){const count=done.filter(q=>q.stat===st.key).length;const mins=done.filter(q=>q.stat===st.key).reduce((n,q)=>n+(q.focusSeconds||0)/60,0);out[st.key]=Math.min(100,Math.max(1,Math.round(1+count*2+Math.sqrt(mins)*0.8+(st.key==="discipline"?state.streak*1.5+rate*10:0))));}out.vitality=Math.min(100,Math.max(1,Math.round(out.vitality+Math.min(10,focus/120))));const unlocked=(state.shadows||[]).map(id=>shadowPerk({id}));for(const sh of (state.dungeonSystem.shadows||[]))unlocked.push({stat:"discipline",amount:1});for(const perk of unlocked)out[perk.stat]=Math.min(100,out[perk.stat]+perk.amount);return out;}
