function renderAiShadowIntro(){if(!$("aiShadowSelect")||!$("aiShadowIntro"))return;const ds=(state.dungeonSystem.shadows||[]).filter(sh=>["S","S+"].includes(String(sh.rank||"").toUpperCase())),sh=ds[Number($("aiShadowSelect").value)||0];if(!sh)return;const type=String(sh.name||"").toLowerCase();let style=/(assassin|dagger|سرعة|خنجر)/i.test(type)?"يركّز على السرعة، إزالة المشتتات، وخطوة تنفيذ فورية.":/(mage|knowledge|archive|ساحر|معرفة)/i.test(type)?"يركّز على التحليل، الفهم العميق، والتجربة قبل الحكم.":/(tank|iron|guardian|حارس|درع)/i.test(type)?"يركّز على الثبات، بناء العادات، وحماية طاقتك من الإرهاق.":"يركّز على الانضباط، التخطيط الواقعي، والتقدم المستمر.";$("aiShadowIntro").innerHTML=`<b>${esc(sh.name)}</b> <span class="tag green">RANK ${esc(sh.rank)}</span><p>${esc(sh.desc||"ظل نخبة يقدم المشورة للصياد.")}</p><small>${style}</small>`;}
function aiShadowReply(message,sh){const m=message.toLowerCase(),name=sh.name||"الظل";let advice;if(/كسل|تسويف|تأجيل|مش قادر|مش قادر|مشتت|تركيز|lazy|procrastin|focus/.test(m))advice="نصيحتي: لا تنتظر الحماس. صغّر المهمة إلى أول خطوة تستغرق 5 دقائق، أبعد مصدر تشتيت واحدًا، واضبط مؤقتًا لـ25 دقيقة. بعد الجلسة قيّم النتيجة بدل أن تحكم على نفسك.";else if(/خطة|هدف|أبدأ|ابدأ|plan|goal|start/.test(m))advice="حوّل الهدف إلى نتيجة واضحة يمكن إثباتها، ثم إلى 3 مراحل. اختر مرحلة واحدة لهذا اليوم وحدد وقت البداية ودليل النجاح. راجع الخطة بعد التنفيذ، لا قبله فقط.";else if(/مهارة|اختبار|اتقان|إتقان|تعلم|skill|test/.test(m))advice="اختر مهمة عملية تشبه استخدام المهارة في الواقع. قيّم نفسك في 4 عناصر: صحة النتيجة، الجودة، الاستقلالية، والقدرة على شرح ما فعلته. سجّل دليلًا حقيقيًا؛ 80/100 حد النجاح في النظام.";else if(/تعب|إرهاق|راحة|ضغط|قلق|tired|stress|rest/.test(m))advice="القوة ليست أن تضغط بلا توقف. خفف حجم المهمة، خذ راحة مناسبة، ولا تعوّض النوم بالتدريب. حافظ على الحد الأدنى الآمن ثم عد تدريجيًا.";else advice="حلّل الأمر إلى: ما النتيجة المطلوبة؟ ما العائق الأكبر؟ وما أصغر خطوة تستطيع تنفيذها اليوم؟ اختر خطوة واحدة، ضع لها موعدًا ودليل إنجاز، ثم راجع ما تعلمته. لا تغيّر الخطة كلها بسبب يوم واحد.";if(/assassin|dagger|سرعة|خنجر/i.test(name))advice="[أسلوب الظل السريع] ابدأ فورًا بخطوة قصيرة وأزل المشتتات. "+advice;else if(/mage|knowledge|archive|ساحر|معرفة/i.test(name))advice="[أسلوب الظل المحلل] افصل الحقائق عن الافتراضات واختبر حلًا صغيرًا. "+advice;else if(/tank|iron|guardian|حارس|درع/i.test(name))advice="[أسلوب الظل الصامد] اختر وتيرة تستطيع الاستمرار عليها دون استنزاف. "+advice;return `${name}: ${advice}`;}
