let selectedSkillPath="web";
function weekKey(d=new Date()){const x=new Date(d);x.setHours(0,0,0,0);x.setDate(x.getDate()-((x.getDay()+6)%7));return x.toISOString().slice(0,10);}
function skillProgress(k){if(k.steps)return Object.values((state.skillSteps||{})[k.id]||{}).filter(Boolean).length;if(k.kind==="done")return state.quests.filter(q=>q.status==="done").length;if(k.kind==="streak")return state.streak;if(k.kind==="intelligence"||k.kind==="strength")return state.quests.filter(q=>q.status==="done"&&q.stat===k.kind).length;return (state.failureReasons||[]).length;}
function renderGrowth(){
 const goals=$("mainGoalsList");if(goals)goals.innerHTML=(state.mainGoals||[]).length?state.mainGoals.map(g=>{const total=(g.milestones||[]).length,done=(g.milestones||[]).filter(m=>m.done).length;return `<div class="goal-card"><b>${esc(g.name)}</b><p>${esc(g.description||"هدف رئيسي")}</p><div class="progress"><i style="width:${total?done/total*100:0}%"></i></div><small>${done}/${total} مراحل مكتملة</small><div class="milestone-list">${(g.milestones||[]).map(m=>`<label><input type="checkbox" data-goal-id="${g.id}" data-milestone-id="${m.id}" ${m.done?"checked":""}> ${esc(m.name)}</label>`).join("")}</div><button class="small-btn complete" data-action="goal-task" data-id="${g.id}">＋ مهمة مرتبطة بالهدف</button></div>`}).join(""):'<div class="empty">لسه مفيش أهداف كبيرة. ابدأ بهدف واحد واضح.</div>';
 const skills=$("skillTreeList"),pathSelect=$("skillPathSelect");if(pathSelect){pathSelect.innerHTML=SKILL_PATHS.map(p=>`<option value="${p.id}">${p.name}</option>`).join("");pathSelect.value=selectedSkillPath;pathSelect.onchange=()=>{selectedSkillPath=pathSelect.value;renderGrowth();};}if(skills){const pathSkills=SKILLS.filter(k=>k.path===selectedSkillPath);skills.innerHTML=`<p class="muted">${esc(SKILL_PATHS.find(p=>p.id===selectedSkillPath)?.desc||"")} — كل مسار له ترتيب واضح، وتمارين عملية، ومشروع أو دليل نهائي.</p>`+pathSkills.map(k=>{const progress=skillProgress(k),unlocked=(state.skillsUnlocked||[]).includes(k.id),previous=pathSkills.find(x=>x.next===k.id),prereq=!previous||(state.skillsUnlocked||[]).includes(previous.id),ready=progress>=k.steps.length&&prereq,checks=(state.skillSteps||{})[k.id]||{};return `<div class="skill-node ${unlocked?"unlocked":""}"><div><b>${unlocked?"✦":"◇"} ${k.name}</b><p>${k.desc}</p><div class="milestone-list">${k.steps.map((step,i)=>`<label><input type="checkbox" data-skill-step="${k.id}" data-step-index="${i}" ${checks[i]?"checked":""} ${!prereq||unlocked?"disabled":""}> ${esc(step)}</label>`).join("")}</div><small>${k.reward} · التقدم ${progress}/${k.steps.length}${!prereq?" · مقفولة حتى اعتماد المرحلة السابقة":""}</small></div><button class="small-btn ${ready?"complete":""}" data-action="unlock-skill" data-id="${k.id}" ${unlocked||!ready?"disabled":""}>${unlocked?"مكتملة ✓":ready?"اعتماد المهارة":"أكمل الخطوات"}</button></div>`}).join("");}
 const wb=$("weeklyBossPanel"),key=weekKey();if(wb){const b=state.weeklyBoss;if(b&&b.week===key){const done=(b.steps||[]).filter(x=>x.done).length;wb.innerHTML=`<div class="boss-box"><span class="tag ${b.status==="defeated"?"green":"red"}">${b.status==="defeated"?"DEFEATED":"ACTIVE BOSS"}</span><h3>${esc(b.name)}</h3><p>${done}/${b.steps.length} مراحل</p><div class="milestone-list">${b.steps.map(st=>`<label><input type="checkbox" data-boss-step="${st.id}" ${st.done?"checked":""} ${b.status==="defeated"?"disabled":""}> ${esc(st.text)}</label>`).join("")}</div>${b.status==="defeated"?"<p>🏆 تم إسقاط الزعيم لهذا الأسبوع.</p>":""}</div>`;$('startWeeklyBossBtn').textContent="الزعيم الحالي نشط";$('startWeeklyBossBtn').disabled=true;}else{wb.innerHTML='<div class="empty">لا يوجد زعيم نشط لهذا الأسبوع.</div>';$('startWeeklyBossBtn').disabled=false;$('startWeeklyBossBtn').textContent="استدعاء زعيم الأسبوع";}}
 const fail=$("failureAnalysisPanel");if(fail){const fr=state.failureReasons||[],counts={};fr.forEach(x=>{const r=x.reason||"لم يُسجل";counts[r]=(counts[r]||0)+1});const top=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,5);fail.innerHTML=fr.length?`<div class="weekly-summary"><span>إجمالي التعثرات المسجلة: <b>${fr.length}</b></span><span>أكثر سبب متكرر: <b>${esc(top[0]?.[0]||"—")}</b></span></div>`+fr.slice(0,8).map(x=>`<div class="stack-item"><span>⚠</span><div class="stack-main"><b>${esc(x.questName)}</b><small>${esc(x.reason)} · ${esc(dateText(x.at))}</small></div></div>`).join(""):'<div class="empty">لما تسجل تعثر، هنطلب منك السبب ونبدأ نطلع الأنماط.</div>';}
 const archive=$("hunterArchiveList");if(archive){const items=[...(state.archive||[]),...(state.history||[]).map(h=>({text:h.text,at:h.at,type:h.type}))].sort((a,b)=>new Date(b.at)-new Date(a.at)).slice(0,25);archive.innerHTML=items.length?items.map(x=>`<div class="stack-item"><span>${x.type==="quest_done"||x.type==="success"?"✓":x.type==="quest_failed"||x.type==="danger"?"⚠":"◈"}</span><div class="stack-main"><b>${esc(x.text)}</b><small>${esc(dateText(x.at))}</small></div></div>`).join(""):'<div class="empty">الأرشيف هيسجل المهمات والترقيات والأحداث المهمة هنا.</div>';}
 const md=$("minimumDayStatus");if(md){const today=new Date().toDateString();md.textContent=(state.minimumDays||[]).includes(today)?"تم تسجيل يوم الحد الأدنى اليوم. الرجوع للمسار أهم من الكمال.":"لم يتم تسجيل يوم الحد الأدنى اليوم.";document.querySelectorAll("[data-minimum]").forEach(el=>el.checked=!!(state.minimumChecklist&&state.minimumChecklist[today]&&state.minimumChecklist[today][el.dataset.minimum]));}
}
function createGoal(e){e.preventDefault();const name=$("goalName").value.trim();if(!name)return;const milestones=$("goalMilestones").value.split(/[،,]/).map(x=>x.trim()).filter(Boolean).map((name,i)=>({id:uid(),name,done:false}));state.mainGoals.unshift({id:uid(),name,description:$("goalDescription").value.trim(),milestones,createdAt:dateNow(),completedTasks:0});state.profile.goal=name;logActivity("إنشاء Main Quest: "+name);save();$("goalForm").reset();render();toast("تم إنشاء الهدف الرئيسي وربط مراحله.");}
function createGoalTask(id){const g=state.mainGoals.find(x=>x.id===id);if(!g)return;const milestone=(g.milestones||[]).find(m=>!m.done);const name=window.prompt("اسم المهمة المرتبطة بالهدف",milestone?milestone.name:g.name);if(!name)return;state.quests.unshift({id:uid(),goalId:g.id,goalMilestoneId:milestone?.id||null,name:name.trim(),type:"main",stat:"discipline",difficulty:"normal",xpReward:25,dcReward:5,deadline:null,description:"مرتبطة بالهدف: "+g.name,focusMinutes:0,focusSeconds:0,focusSessions:0,status:"active",createdAt:dateNow(),completedAt:null,goalId:g.id});logActivity("مهمة مرتبطة بالهدف: "+g.name);save();render();go("quests");toast("تمت إضافة المهمة المرتبطة بالهدف.");}
function saveMinimumDay(){const today=new Date().toDateString(),checks={};document.querySelectorAll("[data-minimum]").forEach(el=>checks[el.dataset.minimum]=el.checked);if(!Object.values(checks).some(Boolean)){toast("اختار خطوة واحدة على الأقل عشان نسجل اليوم.");return;}state.minimumChecklist=state.minimumChecklist||{};state.minimumChecklist[today]=checks;state.minimumDays=state.minimumDays||[];if(!state.minimumDays.includes(today))state.minimumDays.push(today);logActivity("تم تنفيذ Minimum Viable Day");save();render();toast("تم تسجيل يوم الحد الأدنى — حافظت على الاستمرارية من غير مبالغة.");}
function startWeeklyBoss(){const key=weekKey();if(state.weeklyBoss&&state.weeklyBoss.week===key){toast("زعيم الأسبوع الحالي موجود بالفعل.");return;}state.weeklyBoss={week:key,name:"Boss of Consistency",status:"active",steps:[{id:uid(),text:"أكمل 5 مهمات خلال الأسبوع",done:false,kind:"quests"},{id:uid(),text:"نفّذ 3 جلسات تركيز",done:false,kind:"focus"},{id:uid(),text:"راجع هدفك الرئيسي واكتب خطوة تالية",done:false,kind:"review"}]};logActivity("استدعاء زعيم الأسبوع");save();render();toast("ظهر زعيم الأسبوع! واجهه خطوة بخطوة.");}
function toggleBossStep(id,checked){const b=state.weeklyBoss;if(!b||b.status!=="active")return;const st=b.steps.find(x=>x.id===id);if(!st)return;if(checked){if(st.kind==="quests"&&state.quests.filter(q=>q.status==="done"&&q.completedAt&&new Date(q.completedAt)>=new Date(b.week)).length<5){toast("أكمل 5 مهمات فعلية قبل اعتماد المرحلة.");renderGrowth();return;}if(st.kind==="focus"&&(state.focusLogs||[]).filter(x=>new Date(x.completedAt)>=new Date(b.week)).length<3){toast("محتاج 3 جلسات تركيز مسجلة قبل اعتماد المرحلة.");renderGrowth();return;}}st.done=checked;if(b.steps.every(x=>x.done)){b.status="defeated";state.xp+=150;state.coins+=25;updateLevel();transaction("إسقاط زعيم الأسبوع",25,"in");logActivity("هزيمة زعيم الأسبوع +150 XP +25 DC","success");}save();render();}
function unlockSkill(id){const k=SKILLS.find(x=>x.id===id);const prev=k?SKILLS.find(x=>x.path===k.path&&x.next===id):null;if(!k||skillProgress(k)<(k.steps?k.steps.length:k.need)||(prev&&!(state.skillsUnlocked||[]).includes(prev.id))||(state.skillsUnlocked||[]).includes(id))return;state.skillsUnlocked.push(id);state.titles.push(k.name);logActivity("فتح مهارة: "+k.name,"success");save();render();toast("تم فتح المهارة بعد تحقق شرطها الحقيقي!");}
function toggleMilestone(goalId,milestoneId,checked){const g=state.mainGoals.find(x=>x.id===goalId),m=g?.milestones.find(x=>x.id===milestoneId);if(!m)return;m.done=checked;g.updatedAt=dateNow();if(g.milestones.length&&g.milestones.every(x=>x.done)&&!g.rewarded){g.rewarded=true;state.xp+=100;state.coins+=10;updateLevel();transaction("إكمال مراحل الهدف: "+g.name,10,"in");logActivity("إكمال Main Quest: "+g.name,"success");}save();render();}
function renderAchievements(){const el=$("achievementGrid");if(!el)return;const done=state.quests.filter(q=>q.status==="done").length;const defs=[{id:"first",name:"أول خطوة",desc:"أكمل أول مهمة",ok:done>=1},{id:"ten",name:"صياد ناشئ",desc:"أكمل 10 مهمات",ok:done>=10},{id:"fifty",name:"آلة الإنجاز",desc:"أكمل 50 مهمة",ok:done>=50},{id:"streak3",name:"ثلاثة أيام من الاتساق",desc:"سلسلة 3 أيام",ok:state.streak>=3},{id:"streak7",name:"صياد ثابت",desc:"سلسلة 7 أيام",ok:state.streak>=7},{id:"shadow",name:"ARISE",desc:"استخرج أول ظل",ok:state.shadows.length+(state.dungeonSystem.shadows||[]).length>=1},{id:"html",name:"مطور الويب المبتدئ",desc:"اعتمد مهارة HTML",ok:(state.skillsUnlocked||[]).includes("html")},{id:"boss",name:"قاهر الزعيم",desc:"اهزم زعيم أسبوع",ok:state.weeklyBoss?.status==="defeated"},{id:"secret_s_rank_shadows",name:"ملك الظلال",desc:"استخرج 5 ظلال من الفئة S",ok:(state.dungeonSystem.shadows||[]).filter(x=>String(x.rank||"").toUpperCase()==="S").length>=5,secret:true},{id:"secret_night_quests",name:"ساهر الليالي المنضبط",desc:"أكمل 10 مهمات بعد منتصف الليل",ok:(state.archive||[]).filter(x=>x.type==="quest_done"&&new Date(x.at).getHours()<5).length>=10,secret:true},{id:"secret_last_survivor",name:"الناجي الأخير",desc:"فعّل خطة الحد الأدنى وحافظ على الاستمرار بعدها",ok:(state.minimumDays||[]).length>0&&(state.streak||0)>=2,secret:true}];state.achievementsUnlocked=state.achievementsUnlocked||[];defs.forEach(a=>{if(a.ok&&!state.achievementsUnlocked.includes(a.id)){state.achievementsUnlocked.push(a.id);state.archive.unshift({type:"achievement",text:"إنجاز جديد: "+a.name,at:dateNow()});}});el.innerHTML=defs.filter(a=>!a.secret||a.ok).map(a=>`<article class="feature-card"><div class="card-icon">🏆</div><span class="tag green">${a.secret?"SECRET UNLOCKED":"UNLOCKED"}</span><h3>${a.name}</h3><p>${a.desc}</p></article>`).join("");}
function renderMastery(){
 const tests=state.masteryTests||[],campaigns=state.campaigns||[],boss=state.habitBoss;
 const done=state.quests.filter(q=>q.status==="done").length,failed=state.quests.filter(q=>q.status==="failed").length,focus=(state.focusLogs||[]).reduce((n,x)=>n+(x.minutes||0),0);
 const sum=$("masterySummary");if(sum)sum.innerHTML=[["مهام مكتملة",done],["اختبارات ناجحة",tests.filter(t=>t.passed).length],["حملات نشطة",campaigns.filter(c=>!c.done).length],["دقائق التركيز",focus]].map(x=>`<article class="feature-card"><span class="tag">HUNTER DATA</span><h3>${x[1]}</h3><p>${x[0]}</p></article>`).join("");
 const tr=$("masteryResults");if(tr)tr.innerHTML=tests.length?tests.slice(0,8).map(t=>`<div class="stack-item"><span>${t.passed?"🏆":"↻"}</span><div class="stack-main"><b>${esc(t.skill)} — ${t.score}/100</b><small>${t.passed?"اجتاز شرط 80/100":"لم يجتز بعد"} · ${esc(t.evidence||"لا يوجد دليل مسجل")} · ${esc(dateText(t.at))}</small></div></div>`).join(""):'<div class="empty">سجّل أول اختبار عملي لك.</div>';
 const bp=$("habitBossPanel");if(bp)bp.innerHTML=boss?`<div class="boss-box"><span class="tag ${boss.done?"green":"red"}">${boss.done?"DEFEATED":"ACTIVE BOSS"}</span><h3>${esc(boss.name)}</h3><div class="milestone-list">${boss.steps.map((st,i)=>`<label><input type="checkbox" data-habit-step="${i}" ${st.done?"checked":""} ${boss.done?"disabled":""}> ${esc(st.text)}</label>`).join("")}</div><small>${boss.steps.filter(st=>st.done).length}/${boss.steps.length} خطوات</small></div>`:'<div class="empty">لا يوجد زعيم عادة نشط.</div>';
 const cp=$("campaignPanel");if(cp)cp.innerHTML=campaigns.length?campaigns.map(c=>`<div class="goal-card"><b>${esc(c.name)}</b><div class="progress"><i style="width:${c.steps.length?c.steps.filter(st=>st.done).length/c.steps.length*100:0}%"></i></div><div class="milestone-list">${c.steps.map((st,i)=>`<label><input type="checkbox" data-campaign="${c.id}" data-campaign-step="${i}" ${st.done?"checked":""}> ${esc(st.text)}</label>`).join("")}</div></div>`).join(""):'<div class="empty">أنشئ حملة واحدة لتحويل هدفك إلى مراحل.</div>';
 const report=$("hunterWeeklyReport");if(report){const start=new Date();start.setDate(start.getDate()-6);start.setHours(0,0,0,0);const weekDone=state.quests.filter(q=>q.status==="done"&&q.completedAt&&new Date(q.completedAt)>=start).length;const weekFail=state.quests.filter(q=>q.status==="failed"&&((q.failedAt&&new Date(q.failedAt)>=start)||(q.deadline&&new Date(q.deadline)>=start))).length;const weekFocus=(state.focusLogs||[]).filter(x=>x.completedAt&&new Date(x.completedAt)>=start).reduce((n,x)=>n+(x.minutes||0),0);report.innerHTML=`<div class="stack-item"><div class="stack-main"><b>${weekDone} مهمة مكتملة خلال آخر 7 أيام</b><small>${weekFail} حالات تعثر مسجلة</small></div></div><div class="stack-item"><div class="stack-main"><b>${weekFocus} دقيقة تركيز</b><small>البيانات المسجلة فقط</small></div></div><div class="stack-item"><div class="stack-main"><b>${tests.filter(t=>new Date(t.at)>=start&&t.passed).length} اختبارات مهارة ناجحة</b><small>لا تعتمد على XP وحده لإثبات الإتقان</small></div></div><div class="stack-item"><div class="stack-main"><b>الاقتراح التالي</b><small>${weekDone===0?"ابدأ بمهمة صغيرة محددة اليوم.":weekFail>weekDone?"راجع سبب التعثر وصغّر المهمة القادمة.":"حافظ على الوتيرة واختر خطوة أصعب قليلًا."}</small></div></div>`;}
 const wa=$("hunterWeaknessAnalysis");if(wa){const reasons=state.failureReasons||[];const active=state.quests.filter(q=>q.status==="active").length;wa.innerHTML=`<div class="stack-item"><div class="stack-main"><b>مهام نشطة غير مكتملة: ${active}</b><small>${active>=5?"قد يساعدك تقليل المهام النشطة إلى 1–3 أولويات.":"راجع المواعيد وحدد أول خطوة لكل مهمة."}</small></div></div><div class="stack-item"><div class="stack-main"><b>تعثرات مسجلة: ${failed}</b><small>${reasons.length?"أسباب مسجلة: "+[...new Set(reasons.map(x=>x.reason).filter(Boolean))].slice(0,3).map(esc).join("، "):"سجّل سبب التعثر عند فشل مهمة لتحسين دقة التحليل."}</small></div></div><div class="stack-item"><div class="stack-main"><b>ملاحظة منهجية</b><small>التحليل يصف البيانات الموجودة في التطبيق فقط، ولا يستنتج سببًا نفسيًا غير مسجل.</small></div></div>`;}
}
function recordMasteryTest(e){e.preventDefault();const skill=$("masterySkill").value.trim(),score=Number($("masteryScore").value),evidence=$("masteryEvidence").value.trim();if(!skill||!Number.isFinite(score)||score<0||score>100)return;const passed=score>=80;state.masteryTests=state.masteryTests||[];state.masteryTests.unshift({id:uid(),skill,score,evidence,passed,at:dateNow()});state.archive.unshift({type:"mastery_test",text:`اختبار ${skill}: ${score}/100${passed?" — ناجح":" — يحتاج إعادة تدريب"}`,at:dateNow()});if(passed){state.xp+=50;updateLevel();logActivity("اجتياز اختبار مهارة: "+skill,"success");}save();e.target.reset();render();toast(passed?"نجحت في الاختبار! +50 XP. احتفظ بدليل المشروع.":"لم تصل إلى 80/100 بعد. راجع النقاط الضعيفة وأعد المحاولة.");}
function createHabitBoss(e){e.preventDefault();const name=$("habitBossName").value.trim(),steps=$("habitBossSteps").value.split(/[،,\n]/).map(x=>x.trim()).filter(Boolean).map(text=>({text,done:false}));if(!name||!steps.length)return;state.habitBoss={id:uid(),name,steps,createdAt:dateNow(),done:false};logActivity("بدء مواجهة زعيم عادة: "+name);save();e.target.reset();render();toast("بدأت المواجهة. سجّل الخطوات بعد تنفيذها فعلًا.");}
function createCampaign(e){e.preventDefault();const name=$("campaignName").value.trim(),steps=$("campaignSteps").value.split(/[،,\n]/).map(x=>x.trim()).filter(Boolean).map(text=>({text,done:false}));if(!name||!steps.length)return;state.campaigns=state.campaigns||[];state.campaigns.unshift({id:uid(),name,steps,createdAt:dateNow(),done:false});logActivity("إنشاء حملة رئيسية: "+name);save();e.target.reset();render();toast("تم إنشاء الحملة وتقسيمها إلى مراحل.");}
function renderCustomPenaltyTasks(){const el=$("customPenaltyTaskList");if(!el)return;const tasks=state.customPenaltyTasks||[];el.innerHTML=tasks.length?tasks.map(t=>`<div class="stack-item"><span class="stat-icon">⚠</span><div class="stack-main"><b>${esc(t.text)}</b><small>تظهر ضمن اختيارات نافذة منطقة العقوبة</small></div><button type="button" class="small-btn delete" data-action="remove-zone-task" data-id="${esc(t.id)}">إزالة</button></div>`).join(""):'<div class="empty">أضف عقوبة من اختيارك لتظهر هنا وفي النافذة المنبثقة.</div>';}function renderPenalties(){renderCustomPenaltyTasks();$("penaltyList").innerHTML=state.penalties.length?state.penalties.map(p=>`<article class="quest-card"><div class="quest-mark">⚠</div><div class="quest-body"><h3>${esc(p.name)}</h3><p>${esc(p.reason||"لا يوجد سبب محدد")}${p.failureReason?` · سبب الفشل: ${esc(p.failureReason)}`:""} · ${esc(dateText(p.createdAt))}</p><div class="tags"><span class="tag ${p.done?"green":"red"}">${p.done?"تم التنفيذ":"مستحقة"}</span><span class="tag">${p.type==="missed"?"مرتبطة بفشل مهمة":"يدوية"}</span></div></div><div class="quest-actions">${p.done?'<span class="tag green">مكتملة ✓</span>':`<button class="small-btn complete" data-action="complete-penalty" data-id="${p.id}">تأكيد التنفيذ</button>`}<button class="small-btn delete" data-action="delete-penalty" data-id="${p.id}">حذف</button></div></article>`).join(""):'<div class="empty">لا توجد عقوبات. حافظ على توازنك والتزم بما تستطيع الاستمرار فيه.</div>';}
function renderEvolution(){if($("evoAvatar"))$("evoAvatar").innerHTML=avatarMarkup();const r=rank(),idx=rankIndex(),next=RANKS[idx+1];$("evoRank").textContent=r.name;$("evoTitle").textContent=r.title;$("evoDesc").textContent=r.desc;$("rankBar").style.width=(next?Math.min(100,(state.xp-r.min)/(next.min-r.min)*100):100)+"%";$("rankProgressText").textContent=next?`${state.xp-r.min} / ${next.min-r.min} XP إلى الرتبة ${next.name}`:"وصلت إلى أعلى رتبة متاحة حاليًا."; $("rankList").innerHTML=RANKS.map((x,i)=>`<div class="rank-card ${i===idx?"current":i<idx?"passed":""}"><b>${i<idx?"✓":x.name}</b><small>${x.min.toLocaleString()} XP</small></div>`).join("");$("titlesList").innerHTML=state.titles.length?state.titles.map(t=>`<button type="button" class="title-chip ${t===state.profile.activeTitle?"active":""}" data-v9="equip-title" data-title="${esc(t)}">${t===state.profile.activeTitle?"★":"✦"} ${esc(t)}</button>`).join(""):'<span class="muted">ستظهر الألقاب عند تحقيق الإنجازات.</span>';}
let hgN=0;
const HUNTER_PAL=[["#8fa3b8","#2a3647"],["#3df2b1","#0f3b3a"],["#4aa8ff","#10284f"],["#a66bff","#241448"],["#ffcf5a","#4a3210"],["#ff4d5e","#4a1018"],["#f4ecff","#3a1c6b"]];
function hunterSVG(i){const [c,d]=HUNTER_PAL[Math.max(0,Math.min(i,6))],g="hg"+(++hgN);let s=`<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="أفاتار الصياد"><defs><radialGradient id="${g}" cx="50%" cy="38%" r="70%"><stop offset="0" stop-color="${c}" stop-opacity=".45"/><stop offset="1" stop-color="${d}"/></radialGradient></defs><rect width="100" height="100" fill="url(#${g})"/><circle cx="50" cy="50" r="47" fill="none" stroke="${c}" stroke-width="${(1+i*.4).toFixed(1)}" opacity=".55"/>`;
if(i>=3)s+=[[16,22],[84,30],[22,72],[82,66],[50,10]].map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="1.6" fill="${c}"/>`).join("");
if(i>=6)s+=`<g fill="${d}" stroke="${c}" stroke-width="1"><path d="M50 62 L4 28 L14 62 L2 76 L30 74Z"/><path d="M50 62 L96 28 L86 62 L98 76 L70 74Z"/></g>`;
if(i>=5)s+=`<g stroke="${c}" stroke-width="2.4" stroke-linecap="round"><path d="M22 18 L70 78"/><path d="M78 18 L30 78"/></g>`;
if(i>=2)s+=`<path d="M16 100 Q20 56 50 50 Q80 56 84 100Z" fill="${d}" stroke="${c}" stroke-opacity=".6"/>`;
s+=`<path d="M26 100 Q28 66 50 62 Q72 66 74 100Z" fill="#0b1224" stroke="${c}" stroke-width="1.4"/>`;
if(i>=1)s+=`<path d="M26 82 Q50 72 74 82" fill="none" stroke="${c}" stroke-opacity=".7"/>`;
if(i>=4)s+=`<ellipse cx="29" cy="70" rx="9" ry="5" fill="${c}" opacity=".9"/><ellipse cx="71" cy="70" rx="9" ry="5" fill="${c}" opacity=".9"/><path d="M50 74 L55 82 L50 90 L45 82Z" fill="${c}"/>`;
s+=`<rect x="44" y="52" width="12" height="12" rx="3" fill="#10172a"/><circle cx="50" cy="40" r="15" fill="#141b2d" stroke="${c}" stroke-opacity=".5"/>`;
if(i>=1)s+=`<path d="M33 44 Q31 19 50 18 Q69 19 67 44 Q60 31 50 31 Q40 31 33 44Z" fill="${d}" stroke="${c}"/>`;
if(i===5)s+=`<path d="M36 24 L32 10 L44 20Z M64 24 L68 10 L56 20Z" fill="${c}"/>`;
if(i>=6)s+=`<path d="M35 22 L38 8 L45 17 L50 5 L55 17 L62 8 L65 22Z" fill="${c}"/>`;
const eh=i>=4?3:2.2;s+=`<rect x="42" y="${(41-eh/2).toFixed(1)}" width="5.5" height="${eh}" rx="1" fill="${c}"/><rect x="52.5" y="${(41-eh/2).toFixed(1)}" width="5.5" height="${eh}" rx="1" fill="${c}"/></svg>`;
return s;}
function avatarMarkup(){const src=state.profile.avatar;return src?`<img src="${esc(src)}" alt="الصورة الشخصية">`:hunterSVG(rankIndex());}
function avatarChangeAllowed(){return !state.profile.avatar||rankIndex()>=RANKS.length-1||rankIndex()>(Number.isInteger(state.profile.avatarRankIndex)?state.profile.avatarRankIndex:-1);}
function renderAvatar(){const src=state.profile.avatar||"";const fallback=esc((state.profile.name||"H").trim().charAt(0).toUpperCase()||"H");const side=$("sidebarAvatar"),preview=$("profilePhotoPreview");if(side)side.innerHTML=avatarMarkup();if(preview)preview.innerHTML=avatarMarkup();const allowed=avatarChangeAllowed(),status=$("avatarChangeStatus"),label=$("avatarUploadLabel");if(status){if(rankIndex()>=RANKS.length-1)status.textContent="رتبة S+: تقدر تغيّر صورتك في أي وقت.";else if(!src)status.textContent="تقدر تضيف أول صورة الآن. بعدها التغيير يكون عند الترقية التالية.";else if(allowed)status.textContent=`تم فتح تغيير الصورة بعد وصولك لرتبة ${rank().name}.`;else{const next=RANKS[Math.min(rankIndex()+1,RANKS.length-1)];status.textContent=`الصورة مثبتة لهذه الرتبة. التغيير القادم عند الوصول إلى ${next.name}.`;} }if(label)label.classList.toggle("avatar-upload-locked",!!src&&!allowed&&rankIndex()<RANKS.length-1);}
function loadAvatarImage(file){if(!file)return;if(!file.type.match(/^image\/(png|jpeg|webp)$/)){toast("اختار صورة PNG أو JPG أو WEBP.");return;}if(file.size>8*1024*1024){toast("حجم الصورة كبير. اختار صورة أقل من 8 ميجابايت.");return;}if(!avatarChangeAllowed()){toast(`تغيير الصورة مقفول حاليًا. هيتفتح عند الترقية للرتبة التالية، أو بحرية كاملة عند S+.`);return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement("canvas"),max=512,scale=Math.min(1,max/Math.max(img.width,img.height));canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext("2d");ctx.drawImage(img,0,0,canvas.width,canvas.height);let data="";try{data=canvas.toDataURL("image/jpeg",0.82);}catch(err){toast("تعذر تجهيز الصورة. جرّب صورة أخرى.");return;}const previousAvatar=state.profile.avatar,previousRank=state.profile.avatarRankIndex;state.profile.avatar=data;if(rankIndex()<RANKS.length-1)state.profile.avatarRankIndex=rankIndex();else state.profile.avatarRankIndex=RANKS.length-1;logActivity(previousAvatar?"تغيير الصورة الشخصية بعد الترقية":"إضافة الصورة الشخصية");if(!save()){state.profile.avatar=previousAvatar;state.profile.avatarRankIndex=previousRank;return;}render();toast(rankIndex()>=RANKS.length-1?"تم تحديث الصورة — تقدر تغيّرها بحرية عند رتبة S+.":"تم حفظ الصورة الشخصية. التغيير القادم بعد الترقية التالية.");};img.onerror=()=>toast("مش قادر أقرأ الصورة دي. جرّب ملف صورة آخر.");img.src=reader.result;};reader.onerror=()=>toast("تعذر قراءة ملف الصورة.");reader.readAsDataURL(file);}

function startFocus(id){const q=state.quests.find(x=>x.id===id);if(!q||q.status!=="active")return;if(!q.focusMinutes){toast("اختار 25 أو 45 دقيقة من تعديل المهمة أولًا.");return;}if(state.focusSession){toast("في جلسة تركيز موجودة بالفعل. أنهِها أو ألغِها أولًا.");return;}const now=Date.now();state.focusSession={questId:id,minutes:q.focusMinutes,startedAt:new Date(now).toISOString(),endAt:now+q.focusMinutes*60000,status:"running"};save();render();toast(`بدأت جلسة التركيز ${q.focusMinutes} دقيقة. ابعد المشتتات وابدأ.`);}
function stopFocus(){const s=state.focusSession;if(!s)return;if(s.status==="running"){s.status="paused";s.remainingMs=Math.max(0,s.endAt-Date.now());}else if(s.status==="paused"){s.status="running";s.endAt=Date.now()+(s.remainingMs||0);delete s.remainingMs;}save();render();}
function cancelFocus(){if(!state.focusSession)return;confirmAction("إلغاء جلسة التركيز","سيتم إلغاء الجلسة الحالية ولن تُسجل كوقت مكتمل. هل تريد المتابعة؟",()=>{state.focusSession=null;save();render();toast("تم إلغاء جلسة التركيز دون تسجيل وقت مكتمل.");});}
function tickFocus(){const s=state.focusSession;if(!s||s.status!=="running")return;const remain=s.endAt-Date.now();if(remain>0){const el=$("focusGlobalStatus");if(el)el.textContent=`جلسة تركيز نشطة: ${Math.ceil(remain/60000)} دقيقة متبقية`;return;}const q=state.quests.find(x=>x.id===s.questId);if(q){q.focusSeconds=(q.focusSeconds||0)+s.minutes*60;q.focusSessions=(q.focusSessions||0)+1;if(s.minutes>=50&&v9RingReady()){if(v9Distracted(s))logActivity("💍 الخاتم لم يُفعَّل: غادرت الصفحة أثناء الجلسة");else{q.ringDouble=true;logActivity("💍 خاتم التركيز: DC مضاعفة عند إكمال "+q.name,"success");v9Alert("RING ACTIVATED","DC مضاعفة عند إكمال المهمة","completed");}}state.focusLogs.unshift({questId:q.id,questName:q.name,minutes:s.minutes,startedAt:s.startedAt,completedAt:dateNow()});state.focusLogs=state.focusLogs.slice(0,500);logActivity(`اكتملت جلسة تركيز ${s.minutes} دقيقة: ${q.name}`,"success");}state.focusSession=null;save();render();toast("انتهت جلسة التركيز! تم تسجيل الوقت الفعلي للجلسة.");}
function restDay(){const now=new Date(),key=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;state.restDays=state.restDays||[];const used=state.restDays.filter(x=>x.month===key);if(used.some(x=>x.date===now.toDateString())){toast("تم تفعيل يوم الراحة اليوم بالفعل.");return;}if(used.length>=2){toast("استخدمت الحد الأقصى: يومان للراحة هذا الشهر.");return;}confirmAction("تفعيل إجازة طارئة","سيُسجل اليوم كراحة ويحمي سلسلة الالتزام من الانقطاع اليوم فقط. لا يمنح XP ولا يكمل المهام. هل تحتاجه فعلًا؟",()=>{state.restDays.push({date:now.toDateString(),month:key,at:dateNow()});if(state.lastCompleteDate&&new Date(state.lastCompleteDate).toDateString()===new Date(Date.now()-86400000).toDateString())state.lastCompleteDate=dateNow();logActivity("تفعيل يوم راحة طارئ");save();render();toast("تم تسجيل يوم الراحة. خذ راحتك وارجع بخطة واضحة.");});}
function enableNotifications(){if(!("Notification" in window)){toast("المتصفح لا يدعم إشعارات الويب.");return;}Notification.requestPermission().then(permission=>{state.settings.notifications=permission==="granted";save();renderSettings();toast(permission==="granted"?"تم تفعيل الإشعارات المحلية.":"لم يتم منح إذن الإشعارات. تقدر تفعّلها من إعدادات المتصفح.");});}
function checkNotifications(){if(!state.settings.notifications||!("Notification" in window)||Notification.permission!=="granted")return;const now=Date.now();for(const q of state.quests){if(q.status!=="active"||!q.deadline)continue;const diff=new Date(q.deadline).getTime()-now;if(diff>0&&diff<=60*60*1000){const key=`quest-${q.id}-${q.deadline}`;if(!state.notifiedKeys.includes(key)){new Notification("تذكير بالمهمة",{body:`${q.name} — موعدها خلال ساعة.`});state.notifiedKeys.push(key);save();}}}const d=state.dungeonSystem.current;if(d&&d.status==="active"){const diff=new Date(d.deadlineAt).getTime()-now;if(diff>0&&diff<=24*60*60*1000){const key=`dungeon-${d.id}-${d.deadlineAt}`;if(!state.notifiedKeys.includes(key)){new Notification("تذكير بالزنزانة",{body:`تحدي ${d.boss} ينتهي خلال 24 ساعة.`});state.notifiedKeys.push(key);save();}}}}
function backupReminder(){const last=state.lastBackupReminder?new Date(state.lastBackupReminder).getTime():0;if(!last||Date.now()-last>=7*86400000){showNotice("تذكير أسبوعي: صدّر نسخة JSON من الإعدادات لحماية تقدمك. بعد التصدير اضغط زر تأكيد النسخة الاحتياطية.");if($("confirmBackupBtn"))$("confirmBackupBtn").classList.remove("hidden");}}

function renderSettings(){$("playerGoal").value=state.profile.goal||"";if($("strictModeToggle"))$("strictModeToggle").checked=!!state.settings.strictMode;if($("soundToggle"))$("soundToggle").checked=state.settings.sound!==false;if($("restDayStatus")){const now=new Date(),key=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`;const used=(state.restDays||[]).filter(x=>x.month===key).length;$("restDayStatus").textContent=`أيام الراحة المستخدمة هذا الشهر: ${used}/2.`;}if($("enableNotificationsBtn"))$("enableNotificationsBtn").textContent=state.settings.notifications?"✓ الإشعارات مفعلة":"🔔 تفعيل إشعارات المتصفح";$("transactions").innerHTML=state.transactions.length?state.transactions.slice(0,12).map(t=>`<div class="stack-item"><span class="stat-icon">${t.type==="in"?"＋":"－"}</span><div class="stack-main"><b>${esc(t.text)}</b><small>${esc(dateText(t.at))}</small></div><span class="right ${t.amount<0?"danger-text":""}">${t.amount>0?"+":""}${t.amount} DC</span></div>`).join(""):'<div class="empty">لا توجد معاملات حتى الآن.</div>';}
