/* ================= V9 EXTENSIONS =================
   كل ما هو جديد في V9 موجود في هذا القسم + تعديلات صغيرة موسومة بـ v9 داخل الدوال الأصلية.
   الثوابت التالية قابلة للتعديل بأمان. */
const V9_POINTS_PER_LEVEL=3;            // نقاط مهارة لكل مستوى جديد
const V9_RESPEC_COST=50;                // تكلفة إعادة توزيع النقاط (DC)
const V9_ZONE_MIN_FAILS=3;              // عدد المهام الفاشلة في اليوم الذي يفتح Penalty Zone
const V9_ZONE_AUTO_RELEASE_MS=24*3600000; // الإفراج التلقائي بعد 24 ساعة (حتى لا يعلق المستخدم أبدًا)
const V9_RED_FAIL_XP_MULT=2;            // خسارة XP عند فشل Red Gate = XP المهمة × الرقم
const V9_RED_FAIL_XP_CAP=200;
const V9_ATTRS=[
 {k:"str",code:"STR",icon:"💪",name:"القوة البدنية",desc:"+1% XP لكل نقطة في مهام القوة والرشاقة (حتى +25%)."},
 {k:"int",code:"INT",icon:"🧠",name:"الذكاء والتركيز",desc:"+1% XP لكل نقطة في مهام الذكاء والتعلّم (حتى +25%)."},
 {k:"vit",code:"VIT",icon:"❤",name:"الصحة والتعافي",desc:"+1% XP لكل نقطة في مهام الحيوية: نوم، غذاء، تعافي (حتى +25%)."},
 {k:"sen",code:"SEN",icon:"👁",name:"الإدراك والانضباط",desc:"+1% XP لمهام الانضباط، +0.5% DC لكل نقطة (حتى +25%)، وكل 4 نقاط تمتص 1 DC من خصم الفشل (حتى 3)."}
];
const V9_ATTR_OF={strength:"str",agility:"str",intelligence:"int",vitality:"vit",discipline:"sen"};
const V9_ZONE_TASKS=[
 {id:"pushups",text:"50 تمرين ضغط (يمكن تقسيمها على دفعات)",kind:"manual"},
 {id:"steps",text:"المشي 5000 خطوة",kind:"manual"},
 {id:"phone",text:"الامتناع عن الهاتف 3 ساعات متواصلة",kind:"timer",ms:3*3600000},
 {id:"walk",text:"مشي سريع 30 دقيقة (الخيار الأخف)",kind:"manual"}
];
function v9ZoneTaskOptions(){return V9_ZONE_TASKS.concat((state.customPenaltyTasks||[]).map(t=>({...t,kind:"manual",isCustom:true})));}const V9_SIDE_QUESTS=[
 {name:"30 تمرين ضغط الآن",stat:"strength",xp:45,dc:8},
 {name:"اقرأ 10 صفحات فورًا",stat:"intelligence",xp:45,dc:8},
 {name:"امشِ 10 دقائق واشرب كوبين ماء",stat:"vitality",xp:40,dc:7},
 {name:"رتّب مكتبك أو غرفتك 10 دقائق",stat:"discipline",xp:40,dc:7},
 {name:"تنفّس بعمق أو تأمّل 5 دقائق",stat:"vitality",xp:35,dc:6},
 {name:"اكتب 3 أهداف لبكرة",stat:"discipline",xp:35,dc:6},
 {name:"تعلّم 10 كلمات إنجليزية جديدة",stat:"intelligence",xp:45,dc:8},
 {name:"تمرين إطالة 10 دقائق",stat:"agility",xp:40,dc:7}
];
const V9_UNITS={
 knight:{icon:"🛡",ar:"ظل الفارس",buff:"+5% DC لكل فارس (حتى +25%)"},
 mage:{icon:"🔮",ar:"ظل الميج",buff:"−1 DC من خصم الفشل لكل ميج"},
 soldier:{icon:"⚔",ar:"ظل الجندي",buff:"بدون بونص إضافي"}
};
let v9Audio=null,v9PopupTimer=null,v9ZoneShown=false;

function freshV9(){return {equip:{dagger:false,helm:false,ring:false},spent:{str:0,int:0,vit:0,sen:0},lastSeenLevel:1,failToday:{day:null,count:0},zone:{active:false,startedAt:null,reason:"",task:null,phoneOffUntil:null,rerolled:false,taskAccepted:false,cooldownDay:null,history:[]}};}
function v9(){if(!state.v9||typeof state.v9!=="object")ensureV9();return state.v9;}
/* يضمن سلامة بيانات V9 مهما كان مصدر الحالة (حفظ قديم، استيراد، تلف) — ولا يترك المستخدم محبوسًا أبدًا */
function ensureV9(){
  const base=freshV9();
  if(!state.v9||typeof state.v9!=="object"||Array.isArray(state.v9))state.v9=freshV9();
  const v=state.v9;
  if(!Array.isArray(state.inventory))state.inventory=[];
  if(!Array.isArray(state.titles))state.titles=["Awakened"];
  if(!state.settings||typeof state.settings!=="object")state.settings={strictMode:false,notifications:false};
  v.equip={...base.equip,...(v.equip&&typeof v.equip==="object"?v.equip:{})};
  for(const k of Object.keys(base.equip))v.equip[k]=!!v.equip[k]&&!!activeItem(k);
  const sp=v.spent&&typeof v.spent==="object"?v.spent:{};
  v.spent={};V9_ATTRS.forEach(a=>{v.spent[a.k]=Math.max(0,Math.floor(Number(sp[a.k])||0));});
  const total=Math.max(0,((Number(state.level)||1)-1)*V9_POINTS_PER_LEVEL);
  let sum=V9_ATTRS.reduce((n,a)=>n+v.spent[a.k],0);
  while(sum>total){let big=V9_ATTRS[0].k;V9_ATTRS.forEach(a=>{if(v.spent[a.k]>v.spent[big])big=a.k;});v.spent[big]--;sum--;}
  if(!Number.isFinite(v.lastSeenLevel))v.lastSeenLevel=Number(state.level)||1;
  v.failToday={...base.failToday,...(v.failToday&&typeof v.failToday==="object"?v.failToday:{})};
  v.zone={...base.zone,...(v.zone&&typeof v.zone==="object"?v.zone:{})};
  v.zone.active=!!v.zone.active;v.zone.taskAccepted=!!v.zone.taskAccepted;
  if(!Array.isArray(v.zone.history))v.zone.history=[];
  v.zone.history=v.zone.history.slice(0,30);
  if(v.zone.active){
    if(!v.zone.task||typeof v.zone.task!=="object"||!v.zone.task.text)v.zone.active=false;
    else if(!Number.isFinite(new Date(v.zone.startedAt).getTime()))v.zone.startedAt=dateNow();
  }
  if(typeof state.settings.sound!=="boolean")state.settings.sound=true;
  if(typeof state.profile.activeTitle!=="string"||(state.profile.activeTitle&&!state.titles.includes(state.profile.activeTitle)))state.profile.activeTitle="";
  return v;
}

/* ---------- الصوت والتنبيهات (WebAudio بدون ملفات خارجية) ---------- */
function v9Sfx(kind){
  if(!state.settings||!state.settings.sound)return;
  try{
    const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
    v9Audio=v9Audio||new AC();
    if(v9Audio.state==="suspended"&&v9Audio.resume)v9Audio.resume();
    const seq={
      received:[[660,0,.12,"sine"],[990,.12,.2,"sine"],[1320,.26,.32,"triangle"]],
      completed:[[523,0,.12,"triangle"],[659,.1,.12,"triangle"],[784,.2,.14,"triangle"],[1047,.32,.42,"sine"]],
      levelup:[[392,0,.12,"triangle"],[523,.1,.12,"triangle"],[659,.2,.12,"triangle"],[784,.3,.12,"triangle"],[1047,.42,.55,"sine"]],
      alarm:[[196,0,.28,"sawtooth"],[147,.3,.55,"sawtooth"]]
    }[kind];
    if(!seq)return;
    const t0=v9Audio.currentTime+0.02;
    seq.forEach(([f,at,dur,type])=>{const o=v9Audio.createOscillator(),g=v9Audio.createGain(),peak=type==="sawtooth"?0.05:0.11;o.type=type;o.frequency.setValueAtTime(f,t0+at);g.gain.setValueAtTime(0.0001,t0+at);g.gain.exponentialRampToValueAtTime(peak,t0+at+0.02);g.gain.exponentialRampToValueAtTime(0.0001,t0+at+dur);o.connect(g);g.connect(v9Audio.destination);o.start(t0+at);o.stop(t0+at+dur+0.05);});
  }catch(e){}
}
function v9Alert(title,sub,sound){
  const el=$("sysPopup");
  if(el){el.innerHTML=`<div class="sys-popup-box"><span class="sys-popup-tag">[ SYSTEM ]</span><b>${esc(title)}</b><small>${esc(sub||"")}</small></div>`;el.classList.add("show");clearTimeout(v9PopupTimer);v9PopupTimer=setTimeout(()=>el.classList.remove("show"),2600);}
  if(sound)v9Sfx(sound);
}

/* ---------- البوابات Gates ---------- */
function v9Gate(q){const d=q&&q.difficulty;if(d==="red")return{k:"red",icon:"🟥",label:"Red Gate ×2"};if(d==="hard"||d==="elite"||d==="boss")return{k:"yellow",icon:"🟨",label:"B/A Gate"};return{k:"blue",icon:"🟦",label:"E/D Gate"};}

/* ---------- جيش الظلال: الوحدات والبونصات ---------- */
function v9HashId(id){let h=0;String(id).split("").forEach(c=>{h=(h*31+c.charCodeAt(0))%9973;});return h;}
function v9UnitOfMilestone(id){return({first:"soldier",disciplined:"knight",veteran:"mage",elite:"knight",monarch:"mage"})[id]||"soldier";}
function v9UnitOfBoss(s){return s&&s.unit&&V9_UNITS[s.unit]?s.unit:(v9HashId(s&&s.id)%2?"mage":"knight");}
function v9NextUnit(){const n=((state.dungeonSystem&&state.dungeonSystem.shadows)||[]).length;return n%2===0?"knight":"mage";}
function v9Units(){
  const list=[];
  (state.shadows||[]).forEach(id=>{const sh=SHADOWS.find(x=>x.id===id);if(sh)list.push({id,name:sh.name,unit:v9UnitOfMilestone(id)});});
  ((state.dungeonSystem&&state.dungeonSystem.shadows)||[]).forEach(s=>list.push({id:s.id,name:s.name,unit:v9UnitOfBoss(s)}));
  return list;
}
function v9UnitText(id,milestone){const u=milestone?v9UnitOfMilestone(id):v9UnitOfBoss(id);return `${V9_UNITS[u].icon} ${V9_UNITS[u].ar}`;}
function v9ShadowCounts(){const u=v9Units();return{knights:u.filter(x=>x.unit==="knight").length,mages:u.filter(x=>x.unit==="mage").length,total:u.length};}

/* ---------- نقاط المهارة ---------- */
function v9Spent(k){return Math.max(0,Math.floor(Number(v9().spent[k])||0));}
function v9Points(){const total=Math.max(0,((Number(state.level)||1)-1)*V9_POINTS_PER_LEVEL),spent=V9_ATTRS.reduce((n,a)=>n+v9Spent(a.k),0);return{total,spent,available:Math.max(0,total-spent)};}
function v9Bonuses(stat){
  const v=v9(),sc=v9ShadowCounts(),sen=v9Spent("sen"),k=V9_ATTR_OF[stat||"discipline"]||"sen";
  return{
    attrKey:k,
    xpStatPct:Math.min(25,v9Spent(k)),
    daggerPct:v.equip.dagger?20:0,
    dcKnightPct:Math.min(25,sc.knights*5),
    dcSenPct:Math.min(25,sen*0.5),
    lossReduction:Math.min(4,sc.mages+Math.min(3,Math.floor(sen/4)))
  };
}
/* يُستدعى من completeQuest: يطبّق كل البونصات في مكان واحد ويرجع ملاحظات للعرض */
function v9ApplyCompletionBonuses(q,xp,dc){
  const b=v9Bonuses(q.stat),notes=[];
  if(q.difficulty==="red"){xp*=2;dc*=2;notes.push("🟥×2");}
  let xpPct=b.xpStatPct,dcPct=b.dcKnightPct+b.dcSenPct;
  if(b.daggerPct&&new Date().getHours()<12){xpPct+=b.daggerPct;notes.push("🗡 +20% XP");}
  if(b.xpStatPct)notes.push(`+${b.xpStatPct}% XP ${b.attrKey.toUpperCase()}`);
  if(b.dcKnightPct)notes.push(`+${b.dcKnightPct}% DC فرسان`);
  if(b.dcSenPct)notes.push(`+${b.dcSenPct}% DC SEN`);
  xp=Math.ceil(xp*(1+xpPct/100));dc=Math.ceil(dc*(1+dcPct/100));
  if(q.ringDouble){dc*=2;notes.push("💍 DC×2");}
  q.ringDouble=false;
  if(!Number.isFinite(xp))xp=q.xpReward||0;
  if(!Number.isFinite(dc))dc=q.dcReward||0;
  return{xp:Math.min(400,xp),dc:Math.min(100,dc),notes:notes.length?" ("+notes.join(" · ")+")":""};
}
function v9LossReduction(){return v9Bonuses().lossReduction;}
function v9HelmetBlocks(q){
  const v=v9();if(!v.equip.helm||!activeItem("helm"))return false;
  const important=q.type==="daily"||q.type==="main"||q.repeat==="daily"||["elite","boss","red"].includes(q.difficulty);
  if(!important)return false;
  consumeInventory("helm");v.equip.helm=false;
  logActivity("🪖 خوذة الإرادة الصلبة منعت خصم DC عن: "+q.name+" (تحطمت بعد الاستخدام)","success");
  return true;
}
function v9RingReady(){return !!v9().equip.ring&&!!activeItem("ring");}
function v9Distracted(s){const hid=(s.hiddenMs||0)+(s.hiddenAt?Date.now()-s.hiddenAt:0);return hid>120000;}

/* ---------- المعدات واللفافة ---------- */
function v9UseItem(id){
  const def=SHOP.find(x=>x.id===id);if(!def)return false;
  if(def.kind==="equipment"){const e=v9().equip;e[id]=!e[id];logActivity((e[id]?"تجهيز: ":"نزع: ")+def.ar);save();render();toast((e[id]?"تم تجهيز ":"تم نزع ")+def.ar);return true;}
  if(id==="scroll"){v9UseScroll();return true;}
  return false;
}
function v9UseScroll(){
  const used=new Set(state.quests.filter(q=>q.status==="active").map(q=>q.name));
  const pool=V9_SIDE_QUESTS.filter(s=>!used.has("📜 "+s.name));
  if(!pool.length){toast("كل المهام الجانبية نشطة عندك بالفعل. أنجز واحدة أولًا — اللفافة لم تُستهلك.");return;}
  const s=pool[Math.floor(Math.random()*pool.length)];
  state.quests.unshift({id:uid(),name:"📜 "+s.name,type:"emergency",stat:s.stat,difficulty:"normal",xpReward:s.xp,dcReward:s.dc,deadline:null,description:"مهمة جانبية من لفافة الاستدعاء — لا عقوبة على تجاهلها.",focusMinutes:0,repeat:"none",focusSeconds:0,focusSessions:0,status:"active",createdAt:dateNow(),completedAt:null,penaltyCreated:false,dcShielded:false,boostXP:false,boostDC:false,ringDouble:false,sideQuest:true});
  consumeInventory("scroll");
  logActivity("📜 لفافة الاستدعاء: مهمة جانبية — "+s.name,"success");
  save();render();go("quests");v9Alert("QUEST RECEIVED","📜 "+s.name,"received");
}

/* ---------- استخراج ظل من إنجاز كبير (حملة / زعيم عادة) ---------- */
function v9Extract(name,desc){
  const ds=state.dungeonSystem;if(!ds)return;
  ds.shadows=ds.shadows||[];
  if(state.shadows.length+ds.shadows.length>=shadowLimit()){logActivity(`جيش الظلال ممتلئ — لم يُستخرج ظل «${name}»`);return;}
  ds.shadows.unshift({unit:v9NextUnit(),id:"proj-"+uid(),name,rank:rank().name,sourceDungeon:null,arisenAt:dateNow(),desc});
  logActivity(`ARISE: ظل جديد «${name}»`,"success");
  v9Alert("ARISE",name,"levelup");
}

/* ---------- Penalty Zone ---------- */
function v9AfterFail(q,mode){
  const v=v9();
  try{
    if(q.difficulty==="red"&&!q.redPenaltyDone){
      q.redPenaltyDone=true;
      const floor=Math.max(totalXPForLevel(state.level),rank().min); // لا نزول لمستوى أو رتبة أقل
      const want=Math.min(V9_RED_FAIL_XP_CAP,Math.max(0,(Number(q.xpReward)||0)*V9_RED_FAIL_XP_MULT));
      const real=Math.max(0,Math.min(want,state.xp-floor));
      if(real>0){state.xp-=real;logActivity(`🟥 فشل Red Gate: خسارة ${real} XP`,"danger");}
    }
  }catch(e){}
  if(q.sideQuest)return;
  const z=v.zone;if(z.active)return;
  const today=new Date().toDateString();
  if((state.restDays||[]).some(x=>x.date===today))return;      // يوم الراحة يحمي من المنطقة
  
  if(mode==="auto"&&q.deadline&&Date.now()-new Date(q.deadline).getTime()>86400000)return; // مهام قديمة انتهت وأنت غائب لا تحسب
  if(v.failToday.day!==today){v.failToday.day=today;v.failToday.count=0;}
  v.failToday.count++;
  const hard=["elite","boss","red"].includes(q.difficulty);
  v9EnterZone(hard?`فشل مهمة صعبة: ${q.name}`:`فشل المهمة: ${q.name}`);
}
function v9EnterZone(reason){
  const z=v9().zone;if(z.active)return;
  z.active=true;z.startedAt=dateNow();z.reason=reason;z.phoneOffUntil=null;z.rerolled=false;z.taskAccepted=false;
  const options=v9ZoneTaskOptions();z.task={...options[Math.floor(Math.random()*options.length)]};z.taskAccepted=false;
  logActivity("☠ دخول Penalty Zone: "+reason,"danger");
  v9Alert("PENALTY ZONE",reason,"alarm");
}
function v9ExitZone(result){
  const v=v9(),z=v.zone;if(!z.active)return;
  const taskText=z.task&&z.task.text||"";
  z.history.unshift({at:dateNow(),startedAt:z.startedAt,reason:z.reason,task:taskText,result});z.history=z.history.slice(0,30);
  z.active=false;z.cooldownDay=new Date().toDateString();z.task=null;z.phoneOffUntil=null;z.rerolled=false;z.taskAccepted=false;
  if(result==="done"){
    logActivity("✅ خرجت من Penalty Zone بنجاح","success");
    v9Alert("ZONE CLEARED","خرجت من Penalty Zone","levelup");
  }else{
    state.penalties.unshift({id:uid(),name:"Penalty Zone: "+taskText,reason:"انتهت مهلة 24 ساعة دون تنفيذ",type:"missed",done:false,createdAt:dateNow()});
    logActivity("أُفرج عنك تلقائيًا من Penalty Zone وتحولت المهمة إلى عقوبة عادية","danger");
    v9Alert("ZONE RELEASED","تحولت المهمة إلى عقوبة عادية");
  }
  save();render();go("dashboard");
}
function v9ZoneReleaseAt(z){
  const started=new Date(z.startedAt).getTime();
  let at=(Number.isFinite(started)?started:Date.now())+V9_ZONE_AUTO_RELEASE_MS;
  if(z.phoneOffUntil)at=Math.max(at,z.phoneOffUntil+3600000);
  return at;
}
function v9ZoneAction(act){const z=v9().zone;if(!z.active||!z.task)return;
  if(act==="zone-select-task"&&!z.taskAccepted&&!z.phoneOffUntil){const id=$("zoneTaskSelect")?.value,task=v9ZoneTaskOptions().find(t=>t.id===id);if(!task){toast("اختر عقوبة من القائمة أولًا.");return;}z.task={...task};z.taskAccepted=true;save();render();toast("تم اعتماد العقوبة المختارة.");}
  else if(act==="zone-start"&&z.task.kind==="timer"&&!z.phoneOffUntil){if(!z.taskAccepted){toast("اعتمد العقوبة المختارة أولًا.");return;}z.phoneOffUntil=Date.now()+(z.task.ms||10800000);save();render();}
  else if(act==="zone-reroll"&&!z.rerolled&&!z.phoneOffUntil&&!z.taskAccepted){const options=v9ZoneTaskOptions().filter(t=>t.id!==z.task.id);if(!options.length)return;z.task={...options[Math.floor(Math.random()*options.length)]};z.rerolled=true;save();render();}
  else if(act==="zone-done"){if(!z.taskAccepted){toast("اعتمد العقوبة المختارة أولًا.");return;}if(z.task.kind==="timer"&&(!z.phoneOffUntil||Date.now()<z.phoneOffUntil)){toast("لسه العد التنازلي ما خلصش.");return;}confirmAction("تأكيد الخروج من Penalty Zone","هل نفّذت المهمة فعلًا؟ سجّلها بعد التنفيذ فقط.",()=>v9ExitZone("done"));}
  else if(act==="zone-backup")exportBackup();
}function v9RenderZone(){
  const z=v9().zone,ov=$("zoneOverlay");if(!ov)return;const on=!!z.active;ov.classList.toggle("hidden",!on);document.body.classList.toggle("zone-active",on);document.querySelectorAll(".topbar,.shell,.status-fab").forEach(el=>{el.inert=on;});if(on&&!v9ZoneShown)document.querySelectorAll("dialog[open]").forEach(d=>{if(d.id!=="confirmDialog")closeDialog(d.id);});v9ZoneShown=on;const body=$("zoneBody");if(!on||!body)return;
  const t=z.task||{},timer=t.kind==="timer",started=!!z.phoneOffUntil,choices=v9ZoneTaskOptions();
  const chooser=!z.taskAccepted?`<div class="zone-choice"><label for="zoneTaskSelect">اختار العقوبة التي ستنفذها</label><select id="zoneTaskSelect">${choices.map(c=>`<option value="${esc(c.id)}" ${c.id===t.id?"selected":""}>${c.isCustom?"اختيارك: ":""}${esc(c.text)}</option>`).join("")}</select><button type="button" class="primary-btn" data-v9="zone-select-task">اعتماد العقوبة</button></div>`:`<span class="tag green zone-accepted">✓ تم اعتماد العقوبة</span>`;
  body.innerHTML=`<p class="zone-eyebrow">// PENALTY ZONE ACTIVATED //</p><h2>☠ منطقة العقوبة</h2><p class="zone-reason">${esc(z.reason)}</p>${chooser}<div class="zone-task"><span>مهمتك للخروج</span><b>${esc(t.text)}</b></div>${timer?`<div class="zone-timer" id="zoneTimer">${started?"…":z.taskAccepted?"اضغط «ابدأ العد» ثم ابتعد عن هاتفك":"اعتمد المهمة أولًا لبدء المؤقت"}</div>`:""}<div class="zone-actions">${timer&&!started&&z.taskAccepted?'<button type="button" class="primary-btn" data-v9="zone-start">▶ ابدأ العد</button>':""}<button type="button" class="danger-btn" id="zoneDoneBtn" data-v9="zone-done" ${!z.taskAccepted||timer&&(!started||Date.now()<z.phoneOffUntil)?"disabled":""}>✓ أنهيت المهمة</button>${!z.taskAccepted&&!z.rerolled&&!started?'<button type="button" class="ghost-btn" data-v9="zone-reroll">↻ مهمة بديلة (مرة واحدة)</button>':""}<button type="button" class="ghost-btn" data-v9="zone-backup">⇩ نسخة احتياطية</button></div><small class="zone-note" id="zoneRelease"></small><p class="zone-safe">النظام صارم لكنه لا يؤذيك: اختر مهمة مناسبة وآمنة. ولو مرّت 24 ساعة يُفرج عنك تلقائيًا وتتحول المهمة إلى عقوبة عادية في قائمة العقوبات.</p>`;if(t.focusSession){const zt=$("zoneTimer");if(zt&&!started&&z.taskAccepted)zt.textContent="اضغط ابدأ لبدء جلسة التركيز";const zb=body.querySelector("[data-v9=zone-start]");if(zb)zb.textContent="▶ ابدأ جلسة التركيز";}v9Tick();
}function v9Tick(){
  const z=v9().zone;if(!z.active)return;
  const now=Date.now(),release=v9ZoneReleaseAt(z);
  if(now>=release){v9ExitZone("released");return;}
  const rel=$("zoneRelease");
  if(rel){const left=release-now;rel.textContent=`الإفراج التلقائي بعد ${Math.floor(left/3600000)} س ${Math.floor((left%3600000)/60000)} د`;}
  if(z.phoneOffUntil){
    const left=z.phoneOffUntil-now,tm=$("zoneTimer"),btn=$("zoneDoneBtn");
    if(left>0){if(tm){const p=n=>String(n).padStart(2,"0");tm.textContent=`${p(Math.floor(left/3600000))}:${p(Math.floor((left%3600000)/60000))}:${p(Math.floor((left%60000)/1000))}`;}}
    else{if(tm)tm.textContent="انتهى العد — يمكنك إنهاء المهمة الآن";if(btn)btn.disabled=false;}
  }
}

/* ---------- الألقاب ---------- */
function v9CheckTitles(){
  let changed=false;
  const add=t=>{if(!state.titles.includes(t)){state.titles.push(t);logActivity("لقب جديد: "+t,"success");v9Alert("TITLE ACQUIRED",t);changed=true;}};
  const resolved=state.quests.filter(q=>q.status==="done"||q.status==="failed").map(q=>({ok:q.status==="done",t:new Date(q.completedAt||q.failedAt||q.createdAt).getTime()||0})).sort((a,b)=>a.t-b.t);
  let run=0,best=0;resolved.forEach(r=>{run=r.ok?run+1:0;if(run>best)best=run;});
  if(best>=10)add("Wolf Slayer");
  if(rankIndex()>=5)add("Monarch of Shadows");
  if(v9().zone.history.some(h=>h.result==="done"))add("One Who Overcomes");
  if(changed)save();
}
function v9EquipTitle(t){if(!state.titles.includes(t))return;state.profile.activeTitle=state.profile.activeTitle===t?"":t;save();render();}

/* ---------- النقاط ---------- */
function v9Alloc(k){
  if(!V9_ATTRS.some(a=>a.k===k))return;
  if(v9Points().available<=0){toast("لا توجد نقاط متاحة. ارفع مستواك لتحصل على المزيد.");return;}
  v9().spent[k]=v9Spent(k)+1;save();render();v9Sfx("received");
}
function v9Respec(){
  if(v9Points().spent<=0){toast("لا توجد نقاط موزعة لإعادتها.");return;}
  confirmAction("إعادة توزيع النقاط",`ستُسترد كل النقاط الموزعة مقابل ${V9_RESPEC_COST} DC. هل تريد المتابعة؟`,()=>{
    if(state.coins<V9_RESPEC_COST){toast("رصيدك أقل من تكلفة إعادة التوزيع.");return;}
    state.coins-=V9_RESPEC_COST;transaction("إعادة توزيع نقاط المهارة",-V9_RESPEC_COST,"out");
    V9_ATTRS.forEach(a=>{v9().spent[a.k]=0;});logActivity("إعادة توزيع نقاط المهارة");save();render();toast("تمت إعادة النقاط. وزّعها من جديد.");
  });
}

/* ---------- العرض ---------- */
function v9BonusSummary(){
  const v=v9(),sc=v9ShadowCounts(),out=[];
  if(v.equip.dagger)out.push("🗡 خنجر الظل: +20% XP لأي مهمة تُنجز قبل 12 ظهرًا");
  if(v.equip.helm)out.push("🪖 خوذة الإرادة: تمنع خصم DC مرة واحدة");
  if(v.equip.ring)out.push("💍 خاتم التركيز: جلسة 50 دقيقة = DC مضاعفة");
  if(sc.knights)out.push(`🛡 ${sc.knights} فارس: +${Math.min(25,sc.knights*5)}% DC`);
  if(sc.mages)out.push(`🔮 ${sc.mages} ميج: −${Math.min(4,sc.mages)} DC من خصم الفشل`);
  V9_ATTRS.forEach(a=>{const n=v9Spent(a.k);if(n)out.push(`${a.icon} ${a.code} ${n}: ${a.k==="sen"?`+${Math.min(25,n)}% XP انضباط · +${Math.min(25,n*0.5)}% DC`:`+${Math.min(25,n)}% XP`}`);});
  return out;
}
function v9ShadowSVG(unit){
  const body='<ellipse cx="20" cy="14" rx="8" ry="9"/><path d="M6 64 Q8 28 20 24 Q32 28 34 64Z"/>';
  const extra=unit==="knight"?'<path d="M13 7 Q20 -4 27 7 L27 11 L13 11Z"/><rect x="0" y="32" width="10" height="17" rx="3"/>':unit==="mage"?'<path d="M9 11 L20 -10 L31 11Z"/><rect x="34" y="14" width="2.6" height="50"/><circle cx="35.3" cy="12" r="3.4"/>':'<rect x="34" y="4" width="2.4" height="60"/><path d="M33 5 L35.2 -4 L37.4 5Z"/>';
  return `<svg class="shadow-fig" viewBox="-2 -12 44 78" aria-hidden="true">${body}${extra}</svg>`;
}
function v9RenderHeroShadows(){
  const el=$("heroShadows");if(!el)return;
  const units=v9Units(),shown=units.slice(0,8);
  el.innerHTML=shown.map((u,i)=>`<span class="shadow-slot" style="animation-delay:${(i*0.35).toFixed(2)}s" title="${esc(u.name)} — ${esc(V9_UNITS[u.unit].ar)}">${v9ShadowSVG(u.unit)}</span>`).join("")+(units.length>shown.length?`<span class="shadow-more">+${units.length-shown.length}</span>`:"");
}
function v9RenderGates(){
  const el=$("gatesOverview");if(!el)return;
  const c={blue:0,yellow:0,red:0};state.quests.filter(q=>q.status==="active").forEach(q=>{c[v9Gate(q).k]++;});
  el.innerHTML=`<div class="gate-row"><span class="gate-chip blue">🟦 E/D Gates <b>${c.blue}</b></span><span class="gate-chip yellow">🟨 B/A Gates <b>${c.yellow}</b></span><span class="gate-chip red">🟥 Red Gate <b>${c.red}</b></span></div><small class="muted">البوابة تُحدد من الصعوبة. الحمراء (S) للمهمات الأسبوعية أو الرئيسية فقط: مكافأتها ×2، وفشلها يخصم XP (دون أن تهبط تحت مستواك الحالي) ويفتح Penalty Zone.</small>`;
}
function v9RenderAttributes(){
  const pts=v9Points(),badge=$("attrPoints");
  if(badge){badge.textContent=pts.available;badge.classList.toggle("hidden",!pts.available);}
  const grid=$("attrGrid");if(!grid)return;
  $("attrAvailable").textContent=pts.available;
  $("attrTotals").textContent=`المكتسب ${pts.total} · الموزع ${pts.spent} · كل مستوى جديد = ${V9_POINTS_PER_LEVEL} نقاط`;
  grid.innerHTML=V9_ATTRS.map(a=>{const n=v9Spent(a.k);return `<article class="feature-card attr-card"><div class="card-icon">${a.icon}</div><span class="tag">${a.code}</span><h3>${a.name}</h3><p>${a.desc}</p><div class="attr-meter"><i style="width:${Math.min(100,n*4)}%"></i></div><div class="card-bottom"><span class="price">${n} نقطة</span><button type="button" class="primary-btn" data-v9="alloc" data-k="${a.k}" ${pts.available?"":"disabled"}>＋1</button></div></article>`;}).join("");
  const bp=$("bonusPanel");if(bp){const list=v9BonusSummary();bp.innerHTML=list.length?list.map(x=>`<div class="stack-item"><div class="stack-main"><b>${esc(x)}</b></div></div>`).join(""):'<div class="empty">لا توجد بونصات نشطة بعد. وزّع نقاطك أو جهّز معدات من المتجر.</div>';}
  const rb=$("respecBtn");if(rb)rb.textContent=`↺ إعادة التوزيع (${V9_RESPEC_COST} DC)`;
}
function v9HPMP(){
  const today=new Date().toDateString(),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const failedToday=state.quests.filter(q=>q.status==="failed"&&q.failedAt&&new Date(q.failedAt).toDateString()===today).length;
  const mins=(state.focusLogs||[]).filter(l=>l.completedAt&&new Date(l.completedAt).toDateString()===today).reduce((n,l)=>n+(l.minutes||0),0);
  return{hp:clamp(100-15*pendingPenalties().length-10*failedToday,0,100),mp:clamp(Math.round(mins/120*100),0,100),mins};
}
function v9RenderStatus(){
  const el=$("statusBody");if(!el)return;
  const r=rank(),lv=levelProgress(),hm=v9HPMP(),ds=derivedStats(),title=state.profile.activeTitle,sc=v9ShadowCounts(),pts=v9Points(),bonuses=v9BonusSummary();
  el.innerHTML=`<div class="status-top"><div class="status-avatar">${avatarMarkup()}</div><div class="status-id"><small class="status-title">${title?"✦ "+esc(title):"— بدون لقب —"}</small><h2>${esc(state.profile.name||"HUNTER")}</h2><span class="status-rank">${esc(r.title)}</span></div><div class="status-level"><small>LEVEL</small><b>${state.level}</b></div></div>
  <div class="status-bars"><div class="sbar"><span>HP · التزامك الحالي</span><div class="progress"><i class="hp" style="width:${hm.hp}%"></i></div><em>${hm.hp}/100</em></div><div class="sbar"><span>MP · طاقة التركيز اليوم</span><div class="progress"><i class="mp" style="width:${hm.mp}%"></i></div><em>${hm.mins}/120 د</em></div><div class="sbar"><span>XP</span><div class="progress"><i style="width:${lv.percent}%"></i></div><em>${lv.earned.toLocaleString()}/${lv.needed.toLocaleString()}</em></div></div>
  <div class="status-grid"><div><small>GOLD</small><b>◈ ${state.coins} DC</b></div><div><small>RANK</small><b>${esc(r.name)}</b></div><div><small>SHADOWS</small><b>♟ ${sc.total}</b></div><div><small>STREAK</small><b>🔥 ${state.streak||0}</b></div></div>
  <div class="status-stats">${STATS.map(s=>`<span>${s.icon} ${s.name.split(" ")[1]||s.name} <b>${ds[s.key]}</b></span>`).join("")}</div>
  <div class="status-bonus"><b>البونصات النشطة</b>${bonuses.length?bonuses.map(x=>`<small>${esc(x)}</small>`).join(""):"<small>لا يوجد</small>"}</div>
  <div class="status-foot">${pts.available?`<button type="button" class="primary-btn" data-v9="status-to-attr">✧ لديك ${pts.available} نقطة غير موزعة</button>`:""}<button type="button" class="ghost-btn" data-close="statusDialog">إغلاق (Esc)</button></div>`;
}
function v9OpenStatus(){if(v9().zone.active)return;v9RenderStatus();openDialog("statusDialog");}
function v9Render(){
  ensureV9();
  v9CheckTitles();
  const v=v9();
  if(state.level>v.lastSeenLevel){const gained=(state.level-v.lastSeenLevel)*V9_POINTS_PER_LEVEL;v.lastSeenLevel=state.level;v9Alert("LEVEL UP",`LEVEL ${state.level} · +${gained} نقاط مهارة`,"levelup");save();}
  else if(state.level<v.lastSeenLevel){v.lastSeenLevel=state.level;}
  const tl=$("playerTitleSide");if(tl)tl.textContent=state.profile.activeTitle?"✦ "+state.profile.activeTitle:"";
  v9RenderAttributes();v9RenderGates();v9RenderHeroShadows();v9RenderZone();
  const sd=$("statusDialog");if(sd&&sd.open)v9RenderStatus();
}

/* ---------- الأحداث ---------- */
document.addEventListener("click",e=>{
  const a=e.target.closest("[data-v9]");if(!a)return;
  const act=a.dataset.v9;
  if(act==="alloc")v9Alloc(a.dataset.k);
  else if(act==="respec")v9Respec();
  else if(act==="equip-title")v9EquipTitle(a.dataset.title);
  else if(act==="open-status")v9OpenStatus();
  else if(act==="status-to-attr"){closeDialog("statusDialog");go("attributes");}
  else if(act.indexOf("zone-")===0)v9ZoneAction(act);
});
document.addEventListener("keydown",e=>{
  if(e.code!=="KeyS"||e.ctrlKey||e.metaKey||e.altKey||e.shiftKey)return;
  const t=e.target;if(t&&(/^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName)||t.isContentEditable))return;
  if(document.querySelector("dialog[open]"))return;
  e.preventDefault();v9OpenStatus();
});
document.addEventListener("visibilitychange",()=>{
  const s=state.focusSession;if(!s||s.status!=="running")return;
  if(document.hidden)s.hiddenAt=Date.now();
  else if(s.hiddenAt){s.hiddenMs=(s.hiddenMs||0)+(Date.now()-s.hiddenAt);delete s.hiddenAt;save();}
});
if($("statusDialog"))$("statusDialog").addEventListener("click",e=>{if(e.target===e.currentTarget)closeDialog("statusDialog");});
if($("soundToggle"))$("soundToggle").addEventListener("change",e=>{state.settings.sound=e.target.checked;save();if(e.target.checked)v9Sfx("received");});
if($("respecBtn"))$("respecBtn").addEventListener("click",v9Respec);
