  function exportCard(){const c=document.createElement('canvas');c.width=1200;c.height=675;const x=c.getContext('2d'),g=x.createLinearGradient(0,0,1200,675);g.addColorStop(0,'#081426');g.addColorStop(1,'#27152d');x.fillStyle=g;x.fillRect(0,0,1200,675);x.strokeStyle='#55c9ff';x.lineWidth=3;x.strokeRect(30,30,1140,615);x.fillStyle='#a9e9ff';x.font='bold 28px sans-serif';x.fillText('SOLO LEVELING // WEEKLY HUNTER CARD',70,95);x.fillStyle='#fff';x.font='bold 56px sans-serif';x.fillText((state.profile.name||'HUNTER').slice(0,18),70,190);x.font='bold 34px sans-serif';x.fillText(`RANK ${rank().name}  ·  LEVEL ${state.level}`,70,260);const since=Date.now()-7*86400000,done=state.quests.filter(q=>q.status==='done'&&new Date(q.completedAt||0).getTime()>=since).length, xp=state.quests.filter(q=>q.status==='done'&&new Date(q.completedAt||0).getTime()>=since).reduce((a,q)=>a+Number(q.xpReward||0),0);x.font='30px sans-serif';x.fillText(`Quests completed: ${done}`,70,360);x.fillText(`XP earned: ${xp}`,70,420);x.fillText(`Current streak: ${state.streak||0} days`,70,480);x.fillText(`Week of ${new Date().toLocaleDateString()}`,70,570);const a=document.createElement('a');a.download=`hunter-weekly-${today()}.png`;a.href=c.toDataURL('image/png');a.click();}
